// studio_off_tcp_eeprom.ino — обнаружение по UDP, выключение по TCP, память в EEPROM
#include <WiFi.h>
#include <WiFiUdp.h>
#include <EEPROM.h>

const char* WIFI_SSIDS[] = { "DIR-615T-0DBC", "KIBERone", "KIBERone5" };
const char* WIFI_PASSS[] = { "23233010", "KIBERone", "KIBERone" };
const int   NET_COUNT = 3;

const int   TCP_PORT    = 8085;
const int   UDP_PORT    = 8086;
const int   BUTTON      = 4;      // кнопка между GPIO4 и GND, подтяжка внутренняя
const int   WAIT_MS     = 15000;
const unsigned long LISTEN_MS     = 2000;
const unsigned long HOLD_DISCOVER = 3000;
const int   TCP_TIMEOUT = 150;
const int   MAX_PCS     = 20;
const int   EEPROM_SIZE = 512;

WiFiUDP udp;
String ips[MAX_PCS];
int ipCount = 0;

bool connectTo(int idx) {
  WiFi.mode(WIFI_STA);
  WiFi.disconnect(false);
  WiFi.begin(WIFI_SSIDS[idx], WIFI_PASSS[idx]);
  for (int t = 0; t < WAIT_MS / 500; t++) {
    if (WiFi.status() == WL_CONNECTED) return true;
    delay(500);
  }
  return false;
}

void saveIps() {
  EEPROM.begin(EEPROM_SIZE);
  EEPROM.write(0, ipCount);
  int addr = 1;
  for (int i = 0; i < ipCount; i++) {
    for (unsigned int c = 0; c < ips[i].length(); c++) {
      EEPROM.write(addr++, ips[i][c]);
    }
    EEPROM.write(addr++, '\n');
  }
  EEPROM.commit();
}

void loadIps() {
  ipCount = 0;
  EEPROM.begin(EEPROM_SIZE);
  int n = EEPROM.read(0);
  if (n > MAX_PCS) n = MAX_PCS;
  int addr = 1;
  for (int i = 0; i < n; i++) {
    String cur = "";
    while (true) {
      char c = EEPROM.read(addr++);
      if (c == '\n' || c == 0 || c == 255) break;
      cur += c;
    }
    if (cur.length() > 0) ips[ipCount++] = cur;
  }
}

void rememberIp(const String& ip) {
  for (int i = 0; i < ipCount; i++) if (ips[i] == ip) return;
  if (ipCount < MAX_PCS) ips[ipCount++] = ip;
}

void discoverCurrentNet() {
  udp.begin(UDP_PORT);
  for (int r = 0; r < 2; r++) {
    udp.beginPacket(IPAddress(255, 255, 255, 255), UDP_PORT);
    udp.print("SCAN");
    udp.endPacket();
    delay(80);
  }
  unsigned long start = millis();
  char buf[64];
  while (millis() - start < LISTEN_MS) {
    if (udp.parsePacket() > 0) {
      int n = udp.read(buf, 63);
      buf[n] = '\0';
      if (String(buf).startsWith("IAM:")) rememberIp(udp.remoteIP().toString());
    }
    delay(5);
  }
  udp.stop();
  saveIps();
}

void shutdownAll() {
  for (int net = 0; net < NET_COUNT; net++) {
    if (!connectTo(net)) continue;
    for (int i = 0; i < ipCount; i++) {
      WiFiClient client;
      if (client.connect(ips[i].c_str(), TCP_PORT, TCP_TIMEOUT)) {
        client.print("OFF\n");
        client.stop();
      }
    }
  }
  connectTo(0);
}

bool buttonPressed() {
  if (digitalRead(BUTTON) != LOW) return false;
  delay(80);
  return digitalRead(BUTTON) == LOW;
}

void setup() {
  pinMode(BUTTON, INPUT_PULLUP);
  loadIps();
  connectTo(0);
  if (ipCount == 0) {
    if (connectTo(0)) discoverCurrentNet();
  }
}

void loop() {
  static bool wasDown = false;
  static unsigned long downSince = 0;
  static bool actionDone = false;

  bool isDown = buttonPressed();

  if (isDown && !wasDown) { downSince = millis(); actionDone = false; }

  if (isDown && wasDown && !actionDone) {
    if (millis() - downSince >= HOLD_DISCOVER) {
      if (connectTo(0)) discoverCurrentNet();
      actionDone = true;
    }
  }

  if (!isDown && wasDown && !actionDone) {
    if (millis() - downSince >= 100) shutdownAll();
  }

  wasDown = isDown;
  if (WiFi.status() != WL_CONNECTED) connectTo(0);
  delay(10);
}
